```html
<div id="app">
  <h1>Personal Expense Tracker</h1>

  <form id="expense-form">
    <label for="amount">Amount:</label>
    <input type="number" id="amount" step="0.01"><br><br>

    <label for="category">Category:</label>
    <select id="category">
      <option value="groceries">Groceries</option>
      <option value="transport">Transport</option>
      <option value="bills">Bills</option>
      <option value="fun">Fun</option>
    </select><br><br>

    <label for="date">Date:</label>
    <input type="date" id="date"><br><br>

    <label for="note">Note (optional):</label>
    <textarea id="note"></textarea><br><br>

    <button id="add-expense">Add Expense</button>
    <span id="form-error"></span>
  </form>

  <div id="expenses"></div>

  <div id="summary">
    <h2>Category Totals</h2>
    <div class="cat-total" data-cat="groceries">0.00</div>
    <div class="cat-total" data-cat="transport">0.00</div>
    <div class="cat-total" data-cat="bills">0.00</div>
    <div class="cat-total" data-cat="fun">0.00</div>
  </div>

  <div id="filters">
    <h2>Filters</h2>
    <label for="filter-category">Category:</label>
    <select id="filter-category">
      <option value="all">All</option>
      <option value="groceries">Groceries</option>
      <option value="transport">Transport</option>
      <option value="bills">Bills</option>
      <option value="fun">Fun</option>
    </select><br>

    <label for="filter-from">From:</label>
    <input type="date" id="filter-from"><br>

    <label for="filter-to">To:</label>
    <input type="date" id="filter-to"><br>
  </div>

  <span id="total">0.00</span>
</div>

<script>
  const app = document.getElementById('app');
  const expenseForm = document.getElementById('expense-form');
  const expensesDiv = document.getElementById('expenses');
  const totalSpan = document.getElementById('total');
  const catTotalsDiv = document.querySelectorAll('.cat-total');
  const filterCategorySelect = document.getElementById('filter-category');
  const filterFromInput = document.getElementById('filter-from');
  const filterToInput = document.getElementById('filter-to');
  const formErrorSpan = document.getElementById('form-error');

  let expenses = [];
  let filteredExpenses = [];

  function loadExpenses() {
    expenses = JSON.parse(localStorage.getItem('expenses') || '[]');
    renderExpenses();
    updateTotal();
    updateCategoryTotals();
  }

  function renderExpenses() {
    expensesDiv.innerHTML = '';
    filteredExpenses.forEach((expense, index) => {
      const expenseElement = document.createElement('div');
      expenseElement.classList.add('expense');
      expenseElement.innerHTML = `
        ${expense.amount.toFixed(2)} ${expense.category} - ${expense.date}`;
      expenseElement.innerHTML += `<button class="exp-del" data-id="${index}">Delete</button>`;
      expensesDiv.appendChild(expenseElement);
    });
  }

  function updateTotal() {
    let total = 0;
    filteredExpenses.forEach(expense => {
      total += expense.amount;
    });
    totalSpan.textContent = total.toFixed(2);
  }


  function updateCategoryTotals() {
    const categoryTotals = {};
    filteredExpenses.forEach(expense => {
      const cat = expense.category;
      categoryTotals[cat] = (categoryTotals[cat] || 0) + expense.amount;
    });

    catTotalsDiv.forEach(element => {
      const cat = element.dataset.cat;
      element.textContent = categoryTotals[cat].toFixed(2);
    });
  }

  function addExpense() {
    const amount = parseFloat(document.getElementById('amount').value);
    const category = document.getElementById('category').value;
    const date = document.getElementById('date').value;
    const note = document.getElementById('note').value || '';

    if (isNaN(amount) || amount <= 0 || !date) {
      formErrorSpan.textContent = 'Please enter a valid amount and date.';
      return;
    }

    const expense = { amount, category, date, note };
    expenses.push(expense);
    saveExpenses();
    renderExpenses();
    updateTotal();
    updateCategoryTotals();
    document.getElementById('amount').value = '';
    document.getElementById('form-error').textContent = '';

  }

  function deleteExpense(index) {
    expenses.splice(index, 1);
    saveExpenses();
    renderExpenses();
    updateTotal();
    updateCategoryTotals();
  }

  function applyFilters() {
    const categoryFilter = filterCategorySelect.value;
    const fromDate = filterFromInput.value;
    const toDate = filterToInput.value;

    filteredExpenses = expenses.filter(expense => {
      if (categoryFilter !== 'all') {
        return expense.category === categoryFilter;
      }
      return true;
    });

    if (fromDate && toDate) {
      filteredExpenses = filteredExpenses.filter(expense => {
        const expDate = new Date(expense.date);
        const fromDateObj = new Date(fromDate);
        const toDateObj = new Date(toDate);
        return expDate >= fromDateObj && expDate <= toDateObj;
      });
    }

    renderExpenses();
    updateTotal();
    updateCategoryTotals();
  }


  function saveExpenses() {
    localStorage.setItem('expenses', JSON.stringify(expenses));
  }

  loadExpenses();

  expenseForm.addEventListener('submit', (event) => {
    event.preventDefault();
    addExpense();
  });

  expensesDiv.addEventListener('click', (event) => {
    if (event.target.classList.contains('exp-del')) {
      const index = event.target.dataset.id;
      deleteExpense(index);
    }
  });

  filterCategorySelect.addEventListener('change', applyFilters);

  filterFromInput.addEventListener('input', applyFilters);

  filterToInput.addEventListener('input', applyFilters);

</script>
```
